import type { DocAccessLevel } from "./doc-access-level.js";
export type DbAclSubject = "anyone" | "signed-in" | "members" | "editors" | "submitters" | "readers";
export interface DbAcl {
    read?: DbAclSubject[];
    write?: DbAclSubject[];
}
export interface AclCaller {
    readonly access: DocAccessLevel;
    readonly authenticated: boolean;
    readonly blocked?: boolean;
}
export declare const ANON_CALLER: AclCaller;
export declare const canRead: (level: DocAccessLevel) => boolean;
export declare const canWrite: (level: DocAccessLevel) => boolean;
